WITH RECURSIVE x5 AS (SELECT 1 UNION ALL SELECT x4.Name_exp_2 + 1 FROM x8 WHERE x4.1e308 + 1e308 < 100) SELECT x4.Name_exp_2, x4.Name_exp_2, ST_CONTAINS(ST_UNION(ST_ASWKB(ST_INTERSECTION(LINESTRING(POINT(-59, 82), POINT(32, 29)), POINT(2, -5))), ST_CONVEXHULL(ST_GEOMFROMTEXT('MULTIPOINT(8 -8,-7 5)'))), ST_ENVELOPE(ST_GEOMFROMTEXT('LINESTRING(0 0)'))) AS x2, x4.1e308 + 1e308 FROM v19338 AS x4 WHERE x4.Name_exp_2 = 1 AND x4.1e308 + 1e308 < 100